#!/bin/sh
# Build the release tina-wasm-host: rebuild the engine and TUI components
# from THIS checkout's sources, then build the single-file host binary with
# both components embedded and their precompiled (AOT) twins generated by
# wasm.dart's build.rs.
#
# Why rebuild the components instead of shipping the committed artifacts:
# packages/libraries/tina_wasm/bin/engine.wasm is a build product pinned to
# whenever it was last committed (it lags the tree - see its own commit
# messages); a release must carry components built from the release sources
# under the pinned stable SDK, or the wasm binary quietly runs old engine
# code. The TUI component is current more often, but the same rule pins it
# to the release tree.
#
# The recipe mirrors tool/engine_exit_test.sh's build half (the canonical
# local build): materialize the gitignored pubspec_overrides.yaml pointing
# wasm_tools/wasm_components at the wasm.dart checkout, restore the tracked
# pubspec.lock afterwards, build runtime_helpers.wasm on nightly when the
# checkout does not carry it, then compile both components and embed them.
#
# Usage:
#   tool/build_wasm_runner.sh [--wasm-dart <checkout>] [--skip-smoke]
#                             [--smoke-only] [--out <dir>]
# Env (all optional):
#   DART        pinned stable SDK dart (default: $HOME/tools/... then PATH)
#   WASM_DART   wasm.dart checkout (default: sibling ./wasm.dart checkout
#               from CI, else /tmp/m3-wasmdart for local replicas)
#   WASM_DART_REF  fail unless the checkout's HEAD starts with this sha
#   RUNNER_OUT  where to place the binary (default: build/wasm-host)
set -e
cd "$(dirname "$0")/.."
ROOT="$PWD"
PKG="$ROOT/packages/libraries/tina_wasm"
RUNNER_OUT="${RUNNER_OUT:-$ROOT/build/wasm-host}"

SKIP_SMOKE=0
SMOKE_ONLY=0
WASM_DART_CLI=""
while [ $# -gt 0 ]; do
  case "$1" in
    --wasm-dart) WASM_DART_CLI="$2"; shift 2 ;;
    --skip-smoke) SKIP_SMOKE=1; shift ;;
    --smoke-only) SMOKE_ONLY=1; shift ;;
    *) echo "unknown flag: $1" >&2; exit 2 ;;
  esac
done

# --- toolchain capture ------------------------------------------------------
DART="${DART:-$(command -v dart || true)}"
DART="${DART:-$HOME/tools/dart-sdk-3.14.0-stable/bin/dart}"
if [ ! -x "$DART" ]; then
  echo "no dart on PATH and no pinned SDK at $HOME/tools/... ; set DART=" >&2
  exit 1
fi
case "$SMOKE_ONLY" in 1) ;; *)
  case "$("$DART" --version 2>&1)" in
    *"Dart SDK version: 3.14"*) ;;
    *) echo "refusing: $DART is not the pinned stable 3.14.x SDK:" \
        "$("$DART" --version 2>&1)" >&2; exit 1 ;;
  esac ;;
esac

WASM_DART="${WASM_DART_CLI:-${WASM_DART:-$ROOT/wasm.dart}}"
[ -d "$WASM_DART/pkg/wasm_tools" ] || WASM_DART=/tmp/m3-wasmdart
if [ ! -d "$WASM_DART/pkg/wasm_tools" ] || [ ! -d "$WASM_DART/pkg/wasm_components" ]; then
  echo "no wasm.dart checkout (set --wasm-dart or WASM_DART=)" >&2
  exit 1
fi
WASM_DART_HEAD="$(git -C "$WASM_DART" rev-parse HEAD)"
echo "=== wasm.dart checkout: $WASM_DART @ $WASM_DART_HEAD"
if [ -n "${WASM_DART_REF:-}" ]; then
  case "$WASM_DART_HEAD" in
    "$WASM_DART_REF"*) ;;
    *) echo "wasm.dart HEAD $WASM_DART_HEAD is not the pinned $WASM_DART_REF" >&2; exit 1 ;;
  esac
fi

# The wasm_tools build hook expects its cargo artifacts in its own
# workspace root's target/; a global CARGO_TARGET_DIR hides them from the
# hook and kills the build (see engine_exit_test.sh).
unset CARGO_TARGET_DIR
PATH="$HOME/.cargo/bin:$PATH"
export PATH

ENGINE_WASM="$PKG/bin/engine.wasm"
TUI_WASM="$PKG/bin/tui.wasm"

smoke() {
  # Boot the built binary headless against a stub config and wait for the
  # pipes engine's first ready frame. No model call happens: ready precedes
  # any provider traffic, so a dead endpoint is fine (and desirable).
  local bin="$1" cfg ws
  cfg="$(mktemp -d)"
  ws="$(mktemp -d)"
  cat > "$cfg/config" <<EOF
version = 1

[default]
model = "main"

[providers.local]
name = "Local"
base_url = "http://127.0.0.1:9/v1"
models = ["main|Main model"]
EOF
  echo "=== boot smoke: $bin --headless (expect ready frame, deserialize path)"
  # No `timeout` wrapper: GNU coreutils' timeout does not exist on macOS
  # runners (the macos-arm64 release dry-run died at this line before the
  # binary ever launched). None is needed - `--no-stdin` leaves the guest
  # with an immediate-EOF stdin and the pipes engine exits on EOF by
  # design (verified: ready frame, snapshot, `bye` eof, exit 0), so the
  # binary terminates on its own. The assertions below decide pass/fail
  # from the logs; the workflow's step-level timeout-minutes is the
  # backstop should exit-on-EOF ever regress into a hang.
  TINA_WASM_BOOT_TRACE=1 "$bin" --headless --no-stdin \
      --preopen=workspace="$ws" --preopen=config="$cfg" \
      > "$cfg/out.log" 2> "$cfg/err.log" || true
  grep -q '"type":"ready"' "$cfg/out.log" || {
    echo "smoke FAILED: no ready frame on stdout" >&2
    echo '--- stdout tail:'; tail -5 "$cfg/out.log" >&2
    echo '--- stderr tail:'; tail -15 "$cfg/err.log" >&2
    rm -rf "$cfg" "$ws"; return 1;
  }
  grep -q 'host:component-deserialize' "$cfg/err.log" || {
    echo "smoke FAILED: boot trace lacks host:component-deserialize - the binary JIT-compiles at boot instead of deserializing the AOT twin" >&2
    tail -15 "$cfg/err.log" >&2; rm -rf "$cfg" "$ws"; return 1;
  }
  # The boot snapshot (sent right after ready, no model call): the default
  # config selects the full catalog, so plugins must be non-empty and
  # skippedPlugins empty - a plugin that silently stopped mounting on the
  # wasm leg is a release blocker, and this is the cheap place to catch it.
  python3 - "$cfg/out.log" <<'PY'
import json, sys
plugins, skipped = None, None
for line in open(sys.argv[1]):
    if '"type":"snapshot"' not in line:
        continue
    snap = json.loads(line)
    plugins = snap.get("plugins")
    skipped = snap.get("skippedPlugins")
    break
assert plugins, "no snapshot with a plugins array on stdout"
assert skipped == [], f"unexpected skippedPlugins with the default config: {skipped}"
print(f"boot snapshot: {len(plugins)} active plugins, skippedPlugins empty")
print("plugins: " + ", ".join(plugins))
PY
  echo "ready frame + deserialize boot trace confirmed"
  rm -rf "$cfg" "$ws"
}

if [ "$SMOKE_ONLY" = 1 ]; then
  smoke "$RUNNER_OUT/tina-wasm-host"
  exit 0
fi

# --- wasm.dart pin overrides (never clobber an operator's own file) --------
OVERRIDES="$PKG/pubspec_overrides.yaml"
GENERATED_OVERRIDES=0
if [ ! -f "$OVERRIDES" ]; then
  echo "=== writing $OVERRIDES (gitignored; release build pins)"
  cat > "$OVERRIDES" <<EOF
# Generated by tool/build_wasm_runner.sh: the release build pins both
# wasm.dart packages to the paired checkout (repos ship as a pair; the
# workflow checks wasm.dart out at the pinned release ref).
dependency_overrides:
  hooks: 2.2.0
  wasm_components:
    path: $WASM_DART/pkg/wasm_components
  wasm_tools:
    path: $WASM_DART/pkg/wasm_tools
EOF
  GENERATED_OVERRIDES=1
fi
LOCK_BACKUP="$(mktemp)"
cp "$PKG/pubspec.lock" "$LOCK_BACKUP"
cleanup() {
  mv "$LOCK_BACKUP" "$PKG/pubspec.lock" 2>/dev/null || true
  [ "$GENERATED_OVERRIDES" = 1 ] && rm -f "$OVERRIDES"
}
trap cleanup EXIT

echo "=== resolving packages (pinned stable SDK)"
( cd "$PKG" && "$DART" pub get )

# runtime_helpers.wasm is a nightly-cargo build product, untracked in
# wasm.dart; build it inside the resolved wasm_tools package when absent.
WASM_TOOLS_ROOT="$(jq -r '.packages[] | select(.name=="wasm_tools") | .rootUri | sub("^file://"; "")' \
  "$PKG/.dart_tool/package_config.json")"
[ -n "$WASM_TOOLS_ROOT" ] || { echo "wasm_tools not in the resolution" >&2; exit 1; }
if [ ! -f "$WASM_TOOLS_ROOT/assets/runtime_helpers.wasm" ]; then
  echo "=== building runtime_helpers.wasm (nightly cargo, wasm32-unknown-unknown)"
  ( cd "$WASM_TOOLS_ROOT" && ./tool/build_runtime_helpers.sh )
fi

echo "=== building the engine component (from release sources)"
( cd "$PKG" && "$DART" run wasm_tools compile bin/engine.dart )

echo "=== building the TUI component (from release sources)"
( cd "$PKG" && \
  TINA_WASM_ABI=lib/src/components/tina_probe_tui_app.json \
  "$DART" run wasm_tools compile bin/tui.dart )

echo "=== building the host (components embedded + AOT twins by build.rs)"
mkdir -p "$RUNNER_OUT"
( cd "$WASM_DART/pkg/tina_wasm_host" && \
  TINA_WASM_HOST_ENGINE="$ENGINE_WASM" \
  TINA_WASM_HOST_TUI="$TUI_WASM" \
  cargo build --release -p tina-wasm-host 2>&1 | tee "$RUNNER_OUT/build.log" )
BIN="$WASM_DART/target/release/tina-wasm-host"
[ -x "$BIN" ] || { echo "no release binary at $BIN" >&2; exit 1; }

# build.rs logs each precompiled twin as a cargo warning. Both components
# MUST have twins: a release binary that JIT-compiles at boot defeats the
# point of the single-file artifact (and ~doubles first-start latency).
PRECOMPILED="$(grep -Ec '(cargo:warning=)?precompiled .* -> .* bytes' "$RUNNER_OUT/build.log" || true)"
if [ "$PRECOMPILED" -lt 2 ]; then
  echo "expected 2 precompiled-twin warnings (engine + TUI), found $PRECOMPILED" >&2
  exit 1
fi
grep -E '(cargo:warning=)?precompiled .* -> .* bytes' "$RUNNER_OUT/build.log"

cp "$BIN" "$RUNNER_OUT/tina-wasm-host"
cleanup; trap - EXIT

echo "=== artifact"
ls -lh "$RUNNER_OUT/tina-wasm-host" "$ENGINE_WASM" "$TUI_WASM"

if [ "$SKIP_SMOKE" = 1 ]; then
  echo "smoke skipped (--skip-smoke)"
else
  smoke "$RUNNER_OUT/tina-wasm-host"
fi
